        $approval = [
            'id' => 'APPROVAL-PACKET-SELF-CONSTRUCTION-PHASE-5',
            'candidate_id' => data_get($candidate, 'id'),
            'candidate_hash' => data_get($candidatePayload, 'candidate_hash'),
            'status' => 'pending_human_approval',
