                'diff_check' => 'git diff --check',
            ],
            'approval_boundaries' => [
                'packet_completion_is_not_code_approval',
                'integration_report_is_not_merge_authority',
                'human_or_governed_receipt_must_review_before_merge',
                'hot_voice_and_kernel_work_remain_withheld',
            ],
