            'required_tests' => [
                'blocks_duplicate_packet_claim',
                'blocks_overlapping_allowed_files',
                'blocks_hot_scope_claim',
                'blocks_stale_packet_hash',
                'blocks_completion_after_expiry',
                'allows_release_then_reclaim',
