        $buildOptions = [
            'persist_export' => (bool) ($options['persist_export'] ?? false),
        ];
        foreach (['final_completion_human_gate', 'completion_audit', 'completion_evidence', 'completion_receipt', 'runtime_promotion_receipt', 'real_provider_smoke'] as $key) {
